create index bultos_a on bultos (deposito_id, creado);
explain (analyze, buffers, costs off, timing off) select count(*) from bultos
  where deposito_id = 7 and creado >= '2026-03-02' and creado < '2026-03-09';

-- solo existe avisos_todos:
explain (analyze, buffers, costs off, timing off) select id from avisos
  where enviado is null and enviar_desde <= '2026-12-01' order by enviar_desde limit 100;

create index copas_cubre on copas (copa, puntos desc, aciertos desc, ms asc) include (usuario);
vacuum copas;
explain (analyze, buffers, costs off, timing off) select usuario, puntos, aciertos, ms from copas
  where copa = 'pascua-2027' order by puntos desc, aciertos desc, ms asc limit 50;
